function validate([expression]) {
  if (typeof expression !== 'string' || expression.length < 1 || expression.length > 20) return 'expression has 1 to 20 characters.';
  if (!/^\d{1,2}([+\-*]\d{1,2})*$/.test(expression)) return 'expression must be numbers from 0 to 99 joined by +, - or *.';
  const nums = expression.split(/[+\-*]/).map(Number);
  const ops = expression.replace(/\d/g, '').split('');
  const n = nums.length;
  const ways = Array.from({ length: n }, () => Array.from({ length: n }, () => []));
  for (let a = 0; a < n; a++) ways[a][a] = [nums[a]];
  for (let len = 2; len <= n; len++) {
    for (let a = 0; a + len - 1 < n; a++) {
      const b = a + len - 1, out = [];
      for (let k = a; k < b; k++) for (const x of ways[a][k]) for (const y of ways[k + 1][b]) out.push(ops[k] === '+' ? x + y : ops[k] === '-' ? x - y : x * y);
      ways[a][b] = out;
    }
  }
  if (ways[0][n - 1].length > 10000) return 'There can be at most 10^4 results.';
  if (ways[0][n - 1].some(v => v < -(2 ** 31) || v >= 2 ** 31)) return 'Every result must fit in a 32-bit signed integer.';
  return null;
}

