function diffWaysToCompute(expression) {
  const memo = new Map();

  function solve(text) {
    if (memo.has(text)) {
      return memo.get(text);
    }
    const results = [];
    for (let i = 0; i < text.length; i++) {
      const op = text[i];
      if (op !== '+' && op !== '-' && op !== '*') {
        continue;
      }
      const leftResults = solve(text.slice(0, i));
      const rightResults = solve(text.slice(i + 1));
      for (const left of leftResults) {
        for (const right of rightResults) {
          if (op === '+') {
            results.push(left + right);
          } else if (op === '-') {
            results.push(left - right);
          } else {
            results.push(left * right);
          }
        }
      }
    }
    if (results.length === 0) {
      results.push(Number(text));
    }
    memo.set(text, results);
    return results;
  }

  return solve(expression);
}

