        const b = a + len - 1, out = [];
        for (let k = a; k < b; k++) for (const x of ways[a][k]) for (const y of ways[k + 1][b]) out.push(ops[k] === '+' ? x + y : ops[k] === '-' ? x - y : x * y);
        ways[a][b] = out;
      }
    }
    return ways[0][n - 1].every(v => v >= -(2 ** 31) && v < 2 ** 31);
  };
  for (;;) {
    const count = size === 'large' ? 8 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 4);
    // Total length is the digits plus (count - 1) operators and must stay within 20.
    let digitBudget = 21 - count;
    let expression = '';
    for (let i = 0; i < count; i++) {
      const left = count - i - 1;
      const twoDigits = digitBudget - 2 >= left && rand() < (size === 'large' ? 0.25 : 0.35);
      const value = twoDigits ? 10 + Math.floor(rand() * 90) : (rand() < 0.15 ? 0 : 1 + Math.floor(rand() * 9));
      digitBudget -= String(value).length;
      if (i > 0) expression += pick(size === 'large' ? ['+', '-', '-', '*'] : ['+', '-', '*']);
      expression += String(value);
    }
    if (expression.length <= 20 && fits(expression)) return [expression];
  }
}
